'use strict';
(function(){
let state;try{state=JSON.parse(localStorage.getItem('walk-battle-v2'));}catch{}if(!state)state={content:'agiro',actors:[],hp:'',enemyMax:'',ratio:1.2,turns:2};let result=null;
const persist=()=>localStorage.setItem('walk-battle-v2',JSON.stringify(state));
const input=(label,name,value,attrs='')=>`<label>${label}<input name="${name}" value="${esc(value??'')}" ${attrs}></label>`;
const number=(label,name,value,min=0,max='')=>input(label,name,value,`type="number" min="${min}" ${max!==''?`max="${max}"`:''} step="any" required`);
const select=(label,name,values,value)=>`<label>${label}<select name="${name}">${values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
const content=()=>WalkCatalog.contents.find(c=>c.id===state.content)||WalkCatalog.contents[0];
function actorDefault(i){return {name:'キャラ'+(i+1),jobId:'',position:i+1,speed:'',speedMultiplier:1,mp:500,type:'斬撃',weapon:'',hearts:'',attack:{name:'',min:'',max:'',mp:0,hit:1},support:{name:'',kind:'effect',multiplier:1.5,chance:1,duration:2,target:'全員',type:'全種',group:'攻撃強化',mp:0}};}
window.renderBattle=function(){const c=content();$('#view').innerHTML=`<h2>手動・最短ターンの行動計画</h2><p>敵を選び、4人の職業と装備構成を指定して、初手の補助と攻撃の順番を探索します。</p><div class="notice">開発中：職業・装備・こころの同時自動選定は旧「簡易編成」と別の計算です。この画面は入力した4構成の行動計画を比較します。ダメージには対象の敵に対する補助なしの実測範囲を入力してください。特殊効果・敵の反撃・生存可否は未計算です。</div><form id="battle-form"><div class="panel stack"><div class="fields"><label>攻略対象<select id="content-choice">${WalkCatalog.contents.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.category+' / '+x.name)}</option>`).join('')}</select></label>${number('対象1体の参考HP','hp',state.hp||c.hp||'',1)}${number('敵の行動速度の上限（不明なら0）','enemyMax',state.enemyMax||0)}${number('味方の行動順乱数の上限倍率','ratio',state.ratio,1,2)}${select('探索するターン数','turns',['1','2'],String(state.turns))}</div><p class="muted">${esc(c.note)} <a href="${c.source}" target="_blank" rel="noreferrer">参照元</a>（確認日 ${WalkCatalog.checked}）</p><p class="muted">敵の「行動速度の上限」は表示すばやさとは別です。敵側の乱数を含む上限値を入力します。0の場合、敵への先制判定は行いません。味方間の上限倍率は検証情報に基づく仮モデルで変更可能です。</p></div><div class="members">${[0,1,2,3].map(i=>actorForm(state.actors[i]||actorDefault(i),i)).join('')}</div><button class="primary" type="submit">補助の有無 × 行動順24通りを比較 →</button> <button type="button" id="battle-export">計画データを書き出す</button><p class="muted">各キャラの補助は初手に使うかを探索。2ターン目は攻撃固定です。位置・武器・こころ・職業の入れ替え、再行動や連携は自動探索しません。</p></form><div id="battle-results">${renderResults()}</div>`;
$('#content-choice').onchange=e=>{capture(false);state.content=e.target.value;state.hp=content().hp||'';state.enemyMax=0;state.ratio=content().ratio;result=null;persist();renderBattle();};$('#battle-form').onsubmit=e=>{e.preventDefault();try{capture(true);result=BattleEngine.search(state.actors,state);$('#battle-results').innerHTML=renderResults();msg('計算しました。すばやさ調整が必要な候補は現在の構成では順番を保証できません。');}catch(err){msg(err.message);}};$('#battle-export').onclick=()=>{capture(false);download('walk-battle-plan.json',JSON.stringify(state,null,2),'application/json');};};
function actorForm(a,i){const jobs=data.jobs.filter(j=>Number(j.member)===i+1);return `<section class="member"><h3>${esc(a.name)}</h3><div class="fields">${input('名前',`a${i}-name`,a.name,'required')}<label>使用する職業と実レベル<select name="a${i}-jobId" required><option value="">職業を選択</option>${jobs.map(j=>`<option value="${esc(j.id)}" ${a.jobId===j.id?'selected':''}>${esc(j.job)} Lv.${j.level}${j.job.includes('サンプル')?'（仮データ）':''}</option>`).join('')}</select></label>${number('左からの位置（1〜4）',`a${i}-position`,a.position,1,4)}${number('表示すばやさ（装備・こころ込み）',`a${i}-speed`,a.speed)}${number('開幕速度補正の倍率',`a${i}-speedMultiplier`,a.speedMultiplier,.01,10)}${number('戦闘開始時MP',`a${i}-mp`,a.mp)}${select('攻撃の種類',`a${i}-type`,['斬撃','体技','呪文','ブレス'],a.type)}${input('武器・防具構成メモ',`a${i}-weapon`,a.weapon)}${input('こころ構成メモ',`a${i}-hearts`,a.hearts)}</div><h3>攻撃スキル</h3><div class="fields">${input('スキル名',`a${i}-attack-name`,a.attack.name,'required')}${number('対象への最低ダメージ',`a${i}-attack-min`,a.attack.min)}${number('対象への最大ダメージ',`a${i}-attack-max`,a.attack.max)}${number('消費MP',`a${i}-attack-mp`,a.attack.mp)}${number('命中・成立率（0〜1）',`a${i}-attack-hit`,a.attack.hit,0,1)}</div><details><summary>初手に使える補助スキル（任意）</summary><p class="muted">補助後の最終ダメージ倍率を実測から設定します。攻撃力1.4倍がそのままダメージ1.4倍になるとは限りません。同じ効果群は最大値、異なる群は乗算する簡略モデルです。</p><div class="fields">${input('補助名（空欄なら不使用）',`a${i}-support-name`,a.support?.name)}${number('最終ダメージ倍率',`a${i}-support-multiplier`,a.support?.multiplier||1,1,10)}${number('補助成功率（0〜1）',`a${i}-support-chance`,a.support?.chance??1,0,1)}${select('有効ターン数（使用ターン含む）',`a${i}-support-duration`,['1','2'],String(a.support?.duration||2))}${select('効果対象',`a${i}-support-target`,['全員','自身'],a.support?.target||'全員')}${select('強化する攻撃種類',`a${i}-support-type`,['全種','斬撃','体技','呪文','ブレス'],a.support?.type||'全種')}${input('同じ効果として扱う群名',`a${i}-support-group`,a.support?.group||'攻撃強化')}${number('補助の消費MP',`a${i}-support-mp`,a.support?.mp||0)}</div></details></section>`;}
function capture(validate){const form=$('#battle-form'),f=new FormData(form);state.hp=Number(f.get('hp'));state.enemyMax=Number(f.get('enemyMax'));state.ratio=Number(f.get('ratio'));state.turns=Number(f.get('turns'));state.actors=[0,1,2,3].map(i=>{let a=actorDefault(i);['name','jobId','type','weapon','hearts'].forEach(k=>a[k]=f.get(`a${i}-${k}`));['position','speed','speedMultiplier','mp'].forEach(k=>a[k]=Number(f.get(`a${i}-${k}`)));for(const kind of ['attack','support'])for(const k of Object.keys(a[kind])){const value=f.get(`a${i}-${kind}-${k}`);if(value!==null)a[kind][k]=['min','max','mp','hit','multiplier','chance','duration'].includes(k)?Number(value):value;}a.attack.kind='damage';if(!a.support.name)a.support=null;if(validate){if(!data.jobs.some(j=>j.id===a.jobId&&Number(j.member)===i+1))throw Error(`キャラ${i+1}の職業とレベルを登録・選択してください。`);if(a.attack.max<a.attack.min)throw Error('最大ダメージは最低ダメージ以上にしてください。');if(!Number.isInteger(a.position)||a.position<1||a.position>4)throw Error('位置は1〜4の整数です。');if(a.support&&!a.support.group.trim())throw Error('補助の効果群名を入力してください。');}return a;});if(validate&&new Set(state.actors.map(a=>a.position)).size!==4)throw Error('左からの位置は4人で重複しないようにしてください。');persist();}
function renderResults(){if(!result)return '';if(!result.length)return '<p class="notice">MP条件を満たす候補がありません。</p>';return `<p class="notice">以下は入力した実測範囲と補助モデルの成立判定です。実ゲームの確定討伐・周回安定性を保証する結果ではありません。敵の反撃・状態異常・ダメージ上限・回避不可以外の失敗要因は別途確認が必要です。</p>`+result.map((r,i)=>{let end=r.kill?r.low.steps.indexOf(r.kill)+1:r.low.steps.length;let steps=r.low.steps.slice(0,end);return `<article class="panel result"><h3>計画 ${i+1} / ${r.kill?(r.deficit?'最低ダメージは達成・速度調整が必要':'入力モデルの最低ダメージで達成'):r.possible?'上振れ・成功時のみ達成':'目標HPに未達'}</h3><div class="metrics"><div><b>${r.kill?r.kill.turn+'ターン':'未達'}</b><span>最低ダメージでの討伐</span></div><div><b>${r.low.damage.toLocaleString()}</b><span>最大${state.turns}ターンの合計下限</span></div></div><p>左からの並び：${state.actors.map((a,i)=>({...a,i})).sort((a,b)=>a.position-b.position).map(a=>esc(a.name)).join(' → ')}<br>狙う行動順：${r.order.map(i=>esc(state.actors[i].name)).join(' → ')}</p><p class="muted">並び位置の効果はダメージ入力に反映させてください。速度調整後も同じダメージになるとは限らないため、装備変更後に再計算が必要です。</p><div class="tablewrap"><table><thead><tr><th>キャラ</th><th>現在すばやさ</th><th>順番固定の必要値</th><th>追加で必要</th></tr></thead><tbody>${r.order.map(i=>`<tr><td>${esc(state.actors[i].name)}</td><td>${state.actors[i].speed}</td><td>${r.needed[i]}</td><td>+${r.needed[i]-state.actors[i].speed}</td></tr>`).join('')}</tbody></table></div><p class="muted">${state.enemyMax>0?'敵の入力上限値に先制する条件を含みます。':'敵への先制は未判定です。表は味方間の順番を固定するための十分条件です。'}同値を避ける保守的な整数値を採用しています。</p><ol>${steps.map(s=>`<li>${s.turn}ターン目 / ${esc(state.actors[s.index].name)}：${esc(s.skill)} → ${s.damage.toLocaleString()}（累計 ${s.total.toLocaleString()}）</li>`).join('')}</ol><p class="muted">成功・上振れ時の${state.turns}ターン合計：${r.high.damage.toLocaleString()}。最低側では成立率100%未満の補助を適用せず、命中率100%未満の攻撃ダメージを0とします。各キャラのMPはターンごとに消費を検証しています。</p></article>`;}).join('');}
window.renderCatalog=function(){const cat=WalkCatalog;$('#view').innerHTML=`<h2>コンテンツ・最新装備の確認リスト</h2><p>${cat.checked} 確認。${cat.note}</p><div class="notice">方針に合わせ、収録武器は各1本、こころは各4個を仮所持としています。ここは参照用マスターです。性能未登録の装備を架空の評価値で自動編成に混ぜることはしていません。旧「所持装備・こころ」とは別管理です。</div><h3>攻略対象</h3>${cat.contents.map(c=>`<div class="panel sub"><div class="row spread"><h3>${esc(c.category+' / '+c.name)}</h3><span class="pill">${c.end?'終了予定 '+c.end:'終了日未収録・常設区分含む'}</span></div><p>${esc(c.note)}</p><a href="${c.source}" target="_blank" rel="noreferrer">攻略情報を確認</a></div>`).join('')}<h3>最新武器（収録分）</h3>${cat.gear.map(g=>`<div class="panel sub"><h3>${esc(g.name)} <span class="pill">仮所持 ${g.count}本</span></h3><p>${esc(g.skill)} / ${esc(g.type)} / ${esc(g.element)}<br>${esc(g.note)}</p><a href="${g.source}" target="_blank" rel="noreferrer">性能の参照元</a></div>`).join('')}<h3>最新こころ（収録分）</h3>${cat.hearts.map(h=>`<div class="panel sub"><h3>${esc(h.name)} ${esc(h.rank)} <span class="pill">仮所持 ${h.count}個</span></h3><p>コスト ${h.cost} / HP ${h.hp} / ちから ${h.attack} / 攻魔 ${h.magic} / 回魔 ${h.heal} / すばやさ ${h.speed}<br>${esc(h.note)}</p><a href="${h.source}" target="_blank" rel="noreferrer">性能の参照元</a></div>`).join('')}<p class="muted">行動順モデルの出典：<a href="https://9db.jp/dqwalk/data/11777" target="_blank" rel="noreferrer">みんドラの検証記事</a>。味方の通常戦闘1〜1.15、メガモン1〜1.20の範囲を仮採用。敵の乱数は別仕様のため自動推定しません。</p>`;};
})();
